"""docich#4675: a stuck army must still get the field camp recall.

ch1 3-3 ran with next_order None, four castles at one defender each and four
generals unaccounted for. No castle could donate or attack, the monthly pass
had nothing to move, and the opportunistic camp recall was chapter-9 only, so
the army stayed split for the rest of the run.
"""
from docich.hanjuku_speedrun.hanjuku import orchestrator as O


def memory(garrison, active=None):
    return {'chapter': 1, 'month': '3-3', 'world': {'garrison': garrison},
            'plan': {'active': active}}


def test_a_stuck_army_gets_the_field_recall():
    assert O._chapter9_field_recall(memory({'アルマムーン': ['どうし'],
                                            'キカンドン': ['ヴェル']}))


def test_a_castle_with_two_defenders_is_not_stuck():
    assert not O._chapter9_field_recall(memory({'アルマムーン': ['どうし', 'ヴェル'],
                                                'キカンドン': ['ヴェル2']}))


def test_an_active_plan_keeps_the_recall_off():
    assert not O._chapter9_field_recall(memory({'アルマムーン': ['どうし']},
                                              active='A:1:2'))


def test_mechanical_mode_keeps_its_own_rule(monkeypatch):
    from docich.hanjuku_speedrun.hanjuku.strategy import corridor
    monkeypatch.setattr(corridor, 'mechanical', lambda mem: True)
    assert O._chapter9_field_recall(memory({'アルマムーン': ['どうし', 'ヴェル']}))
